SELECT 'DROP INDEX CONCURRENTLY ' || indexrelid::regclass || ';'
FROM pg_index
WHERE indrelid = 'orders'::regclass AND NOT indisvalid
\gexec

-- Create the unique index concurrently
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS orders_external_ref_uidx ON orders(external_ref);

-- Add the unique constraint using the index, with retry logic to avoid long blocks
