DECLARE
    got_lock boolean := false;
BEGIN
    WHILE NOT got_lock LOOP
        BEGIN
            -- Use a short lock timeout to limit blocking of app transactions
            SET LOCAL lock_timeout = '300ms';
            ALTER TABLE orders ADD CONSTRAINT orders_external_ref_unique UNIQUE USING INDEX orders_external_ref_uidx;
            got_lock := true;
        EXCEPTION WHEN lock_not_available THEN
            -- Wait a bit before retrying
            PERFORM pg_sleep(0.5);
        END;
    END LOOP;
END $$;

